'use strict';
const $=id=>document.getElementById(id), pct=x=>(100*x).toFixed(1).replace('.',',')+'%',num=x=>Number(x).toLocaleString('pt-BR',{maximumFractionDigits:2}),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const table=(head,rows)=>'<table><thead><tr>'+head.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
let report,predictions;const labels={livre:'Resultado Livre',lance_positivo:'Lance positivo'};
async function get(path){const r=await fetch(path);if(!r.ok)throw Error('Falha ao carregar '+path);return r.json()}
function showProfile(){const p=(report.clustering.profiles||[]).find(p=>String(p.cluster)===$('profile').value);if(!p){$('profile-info').textContent='Nenhum agrupamento passou nos critérios definidos.';return}const m=p.train_medians;$('profile-info').innerHTML=table(['Característica','Mediana ou quantidade'],[['Processos usados no ajuste',num(p.train_n)],['Áreas da 8ª rodada no perfil',num(p.test_n)],['Área mediana no treino (hectares)',num(Math.expm1(m.log_hectares))],['Idade mediana no treino (anos)',num(m.idade_processo_no_corte)],['Dias com eventos registrados (mediana)',num(m.dias_observados)],['Tipos distintos de evento (mediana)',num(m.eventos_tipos_distintos)],['Frequência de lance positivo na 8ª rodada',p.test_positive_rate===null?'Sem áreas':pct(p.test_positive_rate)],['Frequência de Livre na 8ª rodada',p.test_free_rate===null?'Sem áreas':pct(p.test_free_rate)]])+'<p>Frequências de destino são descrições posteriores; não foram usadas para formar nem escolher os grupos.</p>'}
function simulate(){if(!predictions)return;const target=$('target').value,all=[...predictions[target]].sort((a,b)=>b.score-a.score),fraction=Number($('capacity').value)/100,n=Math.ceil(all.length*fraction),selected=all.slice(0,n),hits=selected.reduce((a,r)=>a+r.observed,0),total=all.reduce((a,r)=>a+r.observed,0);$('capacity-label').textContent=pct(fraction);$('sim-metrics').innerHTML=`<p>Áreas revisadas<strong>${num(n)}</strong></p><p>Ocorrências capturadas<strong>${num(hits)}</strong></p><p>Precisão na seleção<strong>${pct(hits/n)}</strong></p><p>Captura do total<strong>${pct(hits/total)}</strong></p>`;$('sim-table').innerHTML=table(['Ordem','Processo','Área','Pontuação','Alvo observado'],selected.slice(0,25).map((r,i)=>{let [a,y]=r.processo.replaceAll('.','').split('/');a=a.padStart(6,'0');return[i+1,a.slice(0,3)+'.'+a.slice(3)+'/'+y,r.area,num(r.score),r.observed?'Sim':'Não']}))}
async function init(){try{report=await get('pesquisa/experimento_ml_v4.json');const rr=[];for(const [target,d]of Object.entries(report.ranking)){rr.push([labels[target],d.chosen,pct(d.test.precision20),pct(d.test.recall20),num(d.test.lift20)+'×']);for(const[k,v]of Object.entries(d.test_references))rr.push([labels[target]+' · referência',k,pct(v.precision20),pct(v.recall20),num(v.lift20)+'×'])}$('ranks').innerHTML=table(['Objetivo','Método','Precisão 20%','Captura','Ganho sobre aleatório'],rr);$('verdict').textContent='A regra por estado superou os modelos selecionados no topo de 20% da rodada 8 para ambos os objetivos. Compare as referências antes de atribuir vantagem à complexidade do modelo.';const vr=[];for(const[target,d]of Object.entries(report.ranking))for(const[round,items]of Object.entries(d.validation))for(const[k,v]of Object.entries(items))vr.push([labels[target],round,k,pct(v.precision20),num(v.lift20)+'×']);$('validations').innerHTML=table(['Objetivo','Rodada','Método','Precisão 20%','Ganho'],vr);const c=report.clustering;$('cluster-quality').textContent='Configuração selecionada: '+(c.chosen||'nenhuma aprovada')+'. Ajustada em '+num(c.train_processes)+' processos únicos.';$('profile').innerHTML=(c.profiles||[]).map(p=>`<option value="${p.cluster}">Perfil ${p.cluster}</option>`).join('');$('clusters').innerHTML=table(['Configuração','Separação (silhouette)','Estabilidade (ARI)','Menor grupo'],Object.entries(c.candidates).map(([k,v])=>[k,num(v.silhouette),num(v.stability_ari_mean),pct(v.smallest_fraction)]));showProfile();if(c.chosen){const ar=c.candidates[c.chosen].stability_ari_values;$('cluster-quality').textContent+=' Estabilidade média '+num(c.candidates[c.chosen].stability_ari_mean)+', com variação de '+num(Math.min(...ar))+' a '+num(Math.max(...ar))+'. A reamostragem menos estável exige cautela.'}const g=report.regression;$('regression').textContent=`Regressão de lances positivos: atributos ${g.chosen}, erro absoluto médio R$ ${num(g.test.mae)} e R² ${num(g.test.r2)} na rodada 8. Erros elevados impedem recomendar uso para definir lance ou receita.`;$('status').textContent='Executado em '+new Date(report.created_at).toLocaleString('pt-BR')+' · avaliação retrospectiva.'}catch(e){$('status').textContent=e.message}}
$('profile').addEventListener('change',showProfile);$('target').addEventListener('change',simulate);$('capacity').addEventListener('input',simulate);$('load-sim').addEventListener('click',async()=>{const b=$('load-sim');b.disabled=true;b.textContent='Carregando…';try{predictions=await get('pesquisa/predicoes_v4.json');$('sim-controls').hidden=false;b.hidden=true;simulate()}catch(e){b.disabled=false;b.textContent='Tentar novamente';$('status').textContent=e.message}});$('full').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){$('status').textContent='Tela cheia indisponível neste navegador.'}});init();
